        receipts = [
            receipt("z", "A", "D-1", "2026-04-01T10:00:00Z"),
            receipt("a", "A", "D-1", "2026-04-01T12:00:00+02:00"),
        ]
        self.assertEqual(
            run({"command": "count", "protocol": "1", "receipts": receipts}),
            {"protocol": "1", "accepted_count": 1, "duplicate_count": 1},
        )


